-- 1) 29 → HKU Entrance Scholarships (non-local undergraduate entry), rel 10, upcoming, NULL/not_published
UPDATE scholarships SET title = 'HKU Entrance Scholarships (non-local undergraduate entry)', provider = 'The University of Hong Kong', coverage_type = 'Tuition Waiver', amount_usd_value = 0, deadline = 'No separate scholarship application: submit the HKU undergraduate application under the International/Non-JUPAS scheme and you are considered for entrance scholarships automatically, with the scholarship result announced together with the admission offer. The scheme runs in evaluation rounds inside each admissions cycle (for September 2026 entry the first evaluation covered applications received by 26 November 2025 at noon Hong Kong time, with offers from December 2025 and rolling evaluation until 21 August 2026); the next cycle''s dated deadlines were not published on the pages read for this record, so no deadline_date is recorded - apply as early as possible in the cycle.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["Bachelor's"]$j$, eligible_majors = $j$["All full-time undergraduate programmes at the University of Hong Kong (non-local composition fee 2026-27: HK$224,000 per year for non-STEM faculties, HK$249,000 including the STEM fee for Dentistry/Engineering/Medicine/Science and the Schools of Biomedical Engineering, Computing and Data Science and Innovation)"]$j$, eligible_countries = $j$["Non-local undergraduate applicants as defined by HKU/UGC (persons entering Hong Kong for education with a student visa/entry permit, or holding a dependant visa first issued at age 18+, or an IANG visa)"]$j$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$HKU's entrance scholarships are the university's merit awards for new undergraduates, and for non-local entrants they are the main offset against the non-local composition fee (HK$224,000 per year in non-STEM faculties and HK$249,000 including the STEM fee in the STEM faculties and schools, 2026-27). There is no scholarship application to file: every applicant who submits an undergraduate application under HKU's International Admissions / Non-JUPAS scheme is considered for an entrance scholarship automatically, the scholarship result is announced at the same time as the offer of admission, and selection is based on academic merits with consideration of non-academic achievements. The awards are tiered by strength of profile: for top-ranking students an entrance scholarship may go up to a value equivalent to a full tuition fee waiver plus an accommodation scholarship and a living allowance per year; lower tiers are partial. The pool is funded, as HKU puts it, by generous donors, external organisations and governmental bodies in Hong Kong and overseas - the university's scholarship hub lists dozens of entrance schemes behind the umbrella (including faculty- and donor-specific awards, some of which are marked as special scholarships that may require a separate application). Awards cover the normal study period and are renewable subject to satisfactory performance; under the published conditions of award for non-local students, renewal expects a cumulative GPA of 3.0 or above (or a top-25% class ranking for MBBS/BDS students). After enrolment, students can additionally compete for the university's hundreds of in-course merit scholarships. In the September-2026 cycle, evaluation was carried out on applications received by 26 November 2025 (noon HKT) with offers from December 2025, and applications were then evaluated on a rolling basis until 21 August 2026 - so the practical rule every year is to apply as early as possible, because places fill as evaluation proceeds.$desc$, requirements = $req$You must be a non-local applicant (student-visa/dependant-visa/IANG definition) applying to a full-time HKU undergraduate programme through the International/Non-JUPAS route; only one application may be submitted across HKU's admission schemes, with up to three curriculum choices, and the application fee is HK$600 (non-refundable). Consideration for entrance scholarships is automatic on the submitted application - no separate form - and rests on academic merit with non-academic achievements also taken into account; the university may call applicants for an interview or test (not all programmes do, and being invited is not an indicator of admission chances). The scholarship outcome arrives together with the admission offer, and offer-holders normally must accept within three to four weeks (deposit: currently HK$20,000 for non-locals). If you are provisionally admitted you must submit final results for offer confirmation or the offer will be withdrawn. Renewal through the degree requires satisfactory performance (the conditions of award set a cGPA of 3.0 or above, or top-25% ranking for MBBS/BDS), and the award covers only the normal study period. Some special/donor entrance scholarships require a separate application - check the scholarship list on the Fees and Scholarships pages. English-language requirements belong to programme admission (no single scholarship IELTS figure exists) and there is no published single GPA cutoff - grades compete comparatively within each qualification - so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://admissions.hku.hk/fees-and-scholarships/scholarships', source_url = 'https://admissions.hku.hk/fees-and-scholarships/scholarships', application_url = 'https://admissions.hku.hk/fees-and-scholarships/scholarships', recurrence = 'annual', application_status = 'upcoming', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-28 (cleanup pass 114) from the University of Hong Kong's official admissions pages fetched the same day - the Admissions Office FAQ (automatic consideration for an entrance scholarship once the admission application is submitted; result announced with the admission offer; no separate application; selection on academic merits with consideration of non-academic achievements; special scholarships may need separate applications; in-course merit scholarships after admission), the 'General Information' for the International/Non-JUPAS schemes for September 2026 admission (evaluation of applications received by 26 November 2025, 12:00 noon HKT, offers from December 2025 with 3-4 week acceptance windows and rolling evaluation until 21 August 2026; application fee HK$600 non-refundable, one application with up to three curriculum choices; deposit HK$20,000 for non-locals at acceptance; annual composition fees for 2026-27 non-local students HK$224,000 non-STEM and HK$249,000 including the STEM fee; 'The entrance scholarship for top-ranking students may go up to a value equivalent to a full tuition fee waiver plus an accommodation scholarship and a living allowance per year', funded by donors, external organisations and governmental bodies), and the scholarship hub page itself (a filterable list of 43 entrance-type schemes behind the umbrella). Renewal language (cGPA 3.0 or above, or top-25% class ranking for MBBS/BDS, normal-study-period limit, full-time registration) is taken from HKU's published 2024-25 Conditions of Award for non-local entrance scholarships as indexed on admissions.hku.hk the same day. The stored URL still resolves, but only to this filter hub - the record now names the entrance-scholarship family that the stored title ('HKU Entrance Scholarship for International Students') identified, restricted to its non-local undergraduate scope. Award stored as NULL (HKD, 'year', 'variable'): tiered awards from partial support up to full tuition plus accommodation and living allowance - no single figure can represent them. deadline_date NULL/'not_published': the only dated cycle in hand (September 2026 entry) has closed and no dated 2027-entry deadlines were published on the fetched pages; status 'upcoming' ahead of the next cycle's first evaluation round (historically late November). min_gpa/min_ielts NULL. university_scholarships row 523 synced; source 2483 repointed from the bare old path to the live Fees and Scholarships hub. Previous record held the scheme at reliability 4 with no terms read.$note$, award_amount = NULL, award_currency = 'HKD', award_period = 'year', award_basis = 'variable', living_allowance = NULL, funding_type = 'Merit-tiered entrance awards, automatic with the admission application: for top-ranking non-local entrants up to a full tuition fee waiver plus an accommodation scholarship and a living allowance per year (lower tiers partial); covers the normal study period, renewable on satisfactory performance (cGPA 3.0+ under the conditions of award)', tuition_coverage = 'At the top tier the award equals the full annual composition fee (HK$224,000 non-STEM / HK$249,000 STEM in 2026-27) and adds accommodation and living support; most awards are partial - the exact package is stated in the admission offer.', english_requirements = 'No scholarship-level IELTS figure; English-language requirements are set per programme within undergraduate admission.', required_documents = $j$["Online undergraduate application (International/Non-JUPAS scheme) with up to three curriculum choices - scholarship consideration is automatic, no separate form; application fee HK$600 (non-refundable)", "Academic transcripts/results for the qualification presented (and final results for offer confirmation if provisionally admitted); possible interview or test depending on programme", "On accepting an offer: deposit payment (currently HK$20,000 for non-local students) by the date in the offer letter"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "September 2026 entry (fetched scheme document)", "first_evaluation_by": "2025-11-26", "rolling_until": "2026-08-21", "status": "closed"}, {"pattern": "Annual, inside the International/Non-JUPAS application cycle: first evaluation covers applications received by late November (offers from December), then rolling evaluation until late August; scholarship results announced with admission offers"}]$json$ WHERE id = 29 RETURNING id, title, source_reliability;

-- 2) 36 → CUHK Admission Scholarships (incl. non-local students), rel 10, upcoming, NULL/not_published
UPDATE scholarships SET title = 'CUHK Admission Scholarships (incl. non-local students)', provider = 'Chinese University of Hong Kong', coverage_type = 'Tuition Waiver', amount_usd_value = 0, deadline = 'No separate scholarship application at any stage: CUHK identifies qualified new students from the admission applications and informs the selected students of the scholarship offers, so the only deadline is the undergraduate admission application itself (for non-local applicants, the international application rounds for September entry). The same no-application rule covers the university''s nominations for the HKSAR Government Scholarship and the Belt and Road Scholarship.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["Bachelor's"]$j$, eligible_majors = $j$["All full-time undergraduate programmes at the Chinese University of Hong Kong"]$j$, eligible_countries = $j$["Local and non-local new undergraduates with excellent academic or non-academic performance - non-local channels: students from the Chinese Mainland with Gaokao results, and students from other regions with any academic qualifications meeting CUHK undergraduate admission requirements"]$j$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$CUHK offers Admission Scholarships to both local and non-local new undergraduate students on the basis of excellent academic or non-academic performance - and students never apply for them: the university identifies qualified new students from the admissions pool and informs the selected students of the offers. The value of each Admission Scholarship ranges from HK$5,000 to full-tuition coverage; many are renewable for the normative period of the study programme subject to satisfactory academic progress, and some also include an allowance of up to HK$66,000 per year. Non-local eligibility runs in two channels - students from the Chinese Mainland with Gaokao results, and students from other regions holding any academic qualifications that meet CUHK's undergraduate admission requirements - alongside the local JUPAS and non-JUPAS channels. Sitting on the same official scheme page are the government awards for which CUHK nominates first-year students to the Education Bureau (again, no application needed): the HKSAR Government Scholarship (HK$80,000 per year for non-local students; HK$40,000 for locals), designed to attract meritorious non-local students to Hong Kong, and the Belt and Road Scholarship, which covers the tuition fees of outstanding new students - from the six designated countries (Indonesia, Kazakhstan, Malaysia, Mongolia, Myanmar and Thailand) and, since 2019/20, under 'Belt and Road Scholarship (Other Countries)', from other Belt and Road regions as well. The university's own named entrance awards in the same family include the Vice-Chancellor's Scholarships for Excellence (8 non-renewable awards of HK$50,000 a year for distinguished new students in any full-time undergraduate programme, irrespective of admission channel and residency), University Exchange Scholarships awarded on admission (HK$10,000-80,000 on top of an Admission Scholarship for exceptionally outstanding new students), and one-off scholarships of HK$50,000-214,000 for non-local students who excel in non-academic areas such as sports, music, art and science and technology; donor-supported admission scholarships complete the list. Many Admission Scholarship recipients are additionally given the (non-monetary) Honours at Entrance distinction, recorded on the official transcript.$desc$, requirements = $req$There is nothing to submit for the scholarship itself: be a new full-time undergraduate admitted to CUHK with excellent academic or non-academic performance, and the university considers you - selected students are informed of the offer directly. For non-local students the qualifying channels are Mainland Gaokao results, or (for other regions) any academic qualification that meets undergraduate admission requirements. Renewability matters more than entry paperwork: many Admission Scholarships renew for the normative study period only while academic progress stays satisfactory, and the allowance-bearing ones (up to HK$66,000 per year) sit within that same progress logic. The two government schemes on the page work by nomination: CUHK puts forward suitable first-year students to the Education Bureau for the HKSAR Government Scholarship and the Belt and Road Scholarship, so an applicant's job is to be an outstanding admitted non-local student, not to file anything. Ancillary one-offs on the same page (exchange scholarships on admission, non-academic excellence awards for non-locals, the SEN Remarkable Endeavour awards) follow their own announcements, some after the academic year begins. No single numeric GPA cutoff and no scholarship-level IELTS figure are published - selection is comparative within each admission channel and English requirements belong to programme admission - so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://admission.cuhk.edu.hk/fees-financing-your-studies/scholarships/admission-scholarships-for-undergraduates-only/', source_url = 'https://admission.cuhk.edu.hk/fees-financing-your-studies/scholarships/admission-scholarships-for-undergraduates-only/', application_url = 'https://admission.cuhk.edu.hk/fees-financing-your-studies/scholarships/admission-scholarships-for-undergraduates-only/', recurrence = 'annual', application_status = 'upcoming', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-28 (cleanup pass 114) from the Chinese University of Hong Kong's official 'Admission Scholarships (for undergraduates only)' page fetched the same day, in full (both content chunks): admission scholarships for local and non-local new undergraduates on excellent academic or non-academic performance, no application required - the university identifies and informs selected students; values from HK$5,000 to full-tuition coverage, many renewable for the normative period subject to satisfactory academic progress, some with an allowance of up to HK$66,000 per year; eligibility channels - local JUPAS (HKDSE) and non-JUPAS (GCE A-Level/IB/SAT/OSSD/ATAR/Taiwan GSAT/Cambridge Pre-U/sub-degrees etc.), non-local Mainland Gaokao students and non-local students from other regions with any qualifying credentials; the page's scheme list: HKSAR Government Scholarship (fund established 2008; HK$40,000/yr local, HK$80,000/yr non-local; CUHK nominates first-years to the Education Bureau; no application), Belt and Road Scholarship (since 2016/17; six designated countries - Indonesia, Kazakhstan, Malaysia, Mongolia, Myanmar, Thailand - plus Belt and Road (Other Countries) since 2019/20; covers tuition fees; nomination, no application), Vice-Chancellor's Scholarships for Excellence (8 non-renewable HK$50,000 awards yearly, any channel and residency), Exchange Scholarships on admission (HK$10,000-80,000 additional for exceptionally outstanding students), sports scholarships (JUPAS/non-JUPAS local only - not part of this record's non-local emphasis), one-off HK$50,000-214,000 non-academic excellence awards for non-local students, SNDAS scholarships (HK$47,000 non-renewable, local channel), Remarkable Endeavour awards (up to 10 one-off HK$10,000 for SEN new students), non-monetary Honours at Entrance, and donor admission scholarships (Hong Kong Jockey Club Chairman's/Striding On). The stored URL now redirects to a category hub; this subpage is the scheme the stored title ('CUHK International Student Scholarship', bachelor's) identified. Award stored as NULL (HKD, 'year', 'variable'): the family ranges from HK$5,000 to full tuition plus up to HK$66,000/yr allowance, so no single figure represents it. deadline_date NULL/'not_published' by design - there is no scholarship deadline other than the admission application itself; status 'upcoming' ahead of the next September-entry admission cycle. min_gpa/min_ielts NULL. The two government schemes named on the page (HKSAR Government Scholarship; Belt and Road Scholarship) are hosted at several Hong Kong universities and remain candidates for separate records in a future additions batch; here they are documented as nomination routes inside the CUHK family exactly as the page presents them. university_scholarships row 473 synced; source 2479 repointed from the hub to the Admission Scholarships subpage. Previous record held the scheme at reliability 4 with no terms read.$note$, award_amount = NULL, award_currency = 'HKD', award_period = 'year', award_basis = 'variable', living_allowance = NULL, funding_type = 'Automatic merit awards (no application): HK$5,000 up to full-tuition coverage, many renewable for the normative period on satisfactory progress, some with an allowance up to HK$66,000 per year; CUHK also nominates first-years for the HKSAR Government Scholarship (HK$80,000/yr for non-locals) and the Belt and Road Scholarship (tuition coverage)', tuition_coverage = 'At the top of the range an Admission Scholarship covers the full tuition fee, and some add up to HK$66,000 per year towards living costs; smaller one-off awards (from HK$5,000) also exist - the offer letter states the exact package.', english_requirements = 'No scholarship-level IELTS figure; English requirements belong to CUHK undergraduate admission for each qualification channel.', required_documents = $j$["CUHK undergraduate admission application in your channel (non-local: Mainland Gaokao, or other-regions qualifications meeting admission requirements) - scholarship consideration is automatic, no scholarship form exists", "No separate documents for the HKSAR Government Scholarship or Belt and Road Scholarship either: CUHK nominates suitable first-year students to the Education Bureau"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"pattern": "Annual and fully admission-driven: apply for September undergraduate entry in your channel; CUHK identifies recipients from the admitted pool and informs them of Admission Scholarship offers (and of nominations to the government schemes) - there is no scholarship deadline of its own"}]$json$ WHERE id = 36 RETURNING id, title, source_reliability;

-- 3) 51 → HKUST Admissions Scholarships for Non-Local Applicants, rel 10, open, 2026-11-25/fixed
UPDATE scholarships SET title = 'HKUST Admissions Scholarships for Non-Local Applicants', provider = 'Hong Kong University of Science and Technology', coverage_type = 'Tuition Waiver', amount_usd_value = 0, deadline = 'For 2027/28 entry the online application system is OPEN (opened 2 October 2026). Academic admissions scholarships need no separate application - all applicants are considered automatically and normally learn the decision with the admission offer - but timing matters: the Priority Round deadline is 25 November 2026 (offers from late December 2026), after which applications run on a rolling basis from 26 November 2026 until the final closing on 30 June 2027. Application-based awards have their own deadlines (e.g. the need-based Future Leaders Award: admission application by the Priority Round deadline and the award application by 2 December 2026; non-academic SAAS priority deadline 25 November 2026).', deadline_date = '2026-11-25', deadline_type = 'fixed', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["Bachelor's"]$j$, eligible_majors = $j$["All undergraduate programmes at HKUST (non-local tuition fee HK$260,000 per year in 2027/28)"]$j$, eligible_countries = $j$["Non-local undergraduate applicants (holders of a student visa/entry permit, an IANG visa, or a dependant visa first issued at age 18 or above) with international or other qualifications"]$j$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$HKUST's admissions scholarships are its entrance-merit channel for new undergraduates, and for non-local applicants they are measured against a non-local tuition fee of HK$260,000 per year (2027/28). The academic core is automatic: admissions scholarships are awarded to top students from all backgrounds based on academic merit, non-academic achievements and other criteria, all applicants are considered, no separate application is required, and the scholarship decision normally arrives with the admission offer. The channel for holders of international/other qualifications is the University Admissions Scholarship for Other Qualifications Holders: applicants are considered holistically on their profiles, awards may be one-off or renewable and may fully or partially waive tuition fees, and the largest amount of funding is equivalent to the full tuition fee plus an allowance of HK$65,000 per academic year, renewable for the normative duration of study subject to satisfactory academic performance (school top-ups may be added provided the 'full tuition + HK$65,000 allowance' per-year ceiling is not exceeded). Parallel automatic channels exist for other profiles: qualification-banded University Admissions Scholarship schemes (notably for HKDSE holders and, on their own pages, score-banded variants for IB and GCE/International A-Level candidates), the Global Learners Scholarship - a full tuition waiver, renewable for the normal duration subject to satisfactory performance, for applicants of underrepresented nationalities in support of student diversity, also with no application needed - and the Scholarship Scheme for International/Asian Olympiad Medalists. Alongside the automatic academic channel sit application-based awards with separate deadlines: the Future Leaders Award for exceptional non-local students who demonstrate (and must prove) exceptional financial need and resilience - support scaled to need, up to full tuition plus a living allowance, renewable, for direct-from-high-school entrants recommended for admission in the Priority Round - and the non-academic portfolio (Beyond Academic Admissions Scholarship; Student Athletes Admissions Scheme), for which the Priority Round deadline for international-qualification applicants is 25 November 2026. For 2027/28 entry the application system opened on 2 October 2026, the Priority Round closes on 25 November 2026 with offers announced from late December 2026, and rolling applications continue from 26 November 2026 until 30 June 2027.$desc$, requirements = $req$For the automatic academic channel there is only one requirement: apply for undergraduate admission as a non-local applicant - you are considered for academic scholarships without any separate application, holistically on academic merit, non-academic achievements and other criteria, with the decision normally notified together with the admission offer. Renewal of the multi-year awards is conditional on satisfactory academic performance; total funding including any school top-up is capped at full tuition fee plus a HK$65,000 annual allowance. The Global Learners Scholarship is likewise automatic but nationality-based (underrepresented nationalities; full waiver, renewable). The application-based awards demand their own files and dates: for the Future Leaders Award you must be a non-local applicant admitted directly from high school (post-secondary applicants are not eligible), recommended for admission in the Priority Round, and able to demonstrate and document exceptional financial need - admission application by the early (Priority Round) deadline and the award application by 2 December 2026, with a Statement of Circumstance, a Declaration on Family Finances and a reference/recommendation letter; results come from late December 2026 to early January 2027 and acceptance is due by end of January 2027. Non-academic scholarships (SAAS/BAAS) require separate applications (Priority Round deadline 25 November 2026 for international qualifications; late SAAS applications considered case by case until late March 2027). One status warning from the university: any change in local/non-local status after application changes the admissions scheme and can void an existing offer, and inaccurate status information revokes the application and forfeits fees. No single GPA or IELTS figure governs the scholarships (holistic and banded schemes differ by qualification), so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://join.hkust.edu.hk/fees-and-scholarships', source_url = 'https://join.hkust.edu.hk/fees-and-scholarships', application_url = 'https://join.hkust.edu.hk/intlscholarships', recurrence = 'annual', application_status = 'open', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-28 (cleanup pass 114) from HKUST Undergraduate Admissions' official pages fetched the same day - the 'Fees and Scholarships' hub in full (admissions scholarships for outstanding students upon admission; revised government tuition-subsidy criteria and local/non-local definitions with status-change consequences; fees for 2027/28: local HK$49,500, non-local tuition HK$260,000/yr, non-local accommodation ~HK$21,000-51,000 per residential year with university accommodation provided in the first year, personal expenses ~HK$65,000/yr; academic scholarships: top students, academic merit + non-academic achievements, all applicants considered, no separate application; channel links to the University Admissions Scholarship schemes (HKDSE; Other Qualifications), Global Learners and Olympiad Medalists; non-academic application deadlines: Priority Round 25 November 2026 for international qualifications (late SAAS case by case until late March 2027), early January 2027 for JUPAS; BAAS/SAAS links), the 'University Admissions Scholarship for Other Qualifications Holders' page (holistic consideration on profiles; one-off or renewable, full or partial tuition waivers; largest funding = full tuition fee plus HK$65,000 per academic year renewable for the normative duration subject to satisfactory performance; school top-ups capped at that ceiling; no separate application; decision with the admission offer), the international-qualifications scholarships page (2027/28 timeline: system opened early October 2026, Priority Round deadline 25 November 2026, rolling applications from 26 November 2026, offers from late December 2026, application closes 30 June 2027), and the award pages for the Global Learners Scholarship (diversity objective; automatic for underrepresented nationalities; full tuition waiver renewable subject to satisfactory academic performance; ceiling incl. top-ups as above) and the Future Leaders Award (exceptional non-local students with financial need and academic excellence; resilience and community contribution; proof of exceptional financial need required; direct-from-high-school only and Priority-Round admission recommendation; support scaled to need up to full tuition plus living allowance, renewable; admission application by the early-round deadline and award application by 2 December 2026 with Statement of Circumstance, Declaration on Family Finances and reference letter; results late December 2026-early January 2027, acceptance by end of January 2027). The previously stored URL (join.hkust.edu.hk/scholarships/) returns 404; the family now lives on the Fees and Scholarships hub. Title normalised from 'HKUST University Scholarship for Non-Local Students'. Award stored as NULL (HKD, 'year', 'variable'): awards range from partial one-off waivers to full tuition plus HK$65,000/yr renewable. financial_need_based stays false at record level because the core academic channel is merit-based; the need-based Future Leaders Award is documented as the named sibling within the family (a standalone record for it remains a future-additions candidate). deadline_date 2026-11-25 ('fixed') is the 2027/28 Priority Round deadline read on three fetched pages, with status 'open' (system opened 2 October 2026); the 30 June 2027 rolling close and the 2 December 2026 Future-Leaders deadline are in the deadline text and rounds JSON. min_gpa/min_ielts NULL. university_scholarships row 461 synced; source 2548 repointed from the dead /scholarships/ path to the live hub. Previous record held the scheme at reliability 4 behind a 404 with no terms read.$note$, award_amount = NULL, award_currency = 'HKD', award_period = 'year', award_basis = 'variable', living_allowance = NULL, funding_type = 'Automatic academic awards: one-off or renewable full/partial tuition waivers, up to a maximum funding of full tuition plus HK$65,000 per year allowance renewable for the normative duration; siblings include the Global Learners full-waiver (underrepresented nationalities), Olympiad-medalist scheme, and application-based Future Leaders (need-based) and non-academic awards', tuition_coverage = 'The tuition fee (HK$260,000/yr for non-locals in 2027/28) can be waived in part or in full; top packages add an allowance of up to HK$65,000 per year towards living costs (university accommodation ~HK$21,000-51,000/yr; personal expenses ~HK$65,000/yr).', english_requirements = 'No scholarship-level IELTS figure; English-language requirements sit inside undergraduate admission and vary by qualification.', required_documents = $j$["Online undergraduate admission application as a non-local applicant - academic scholarship consideration is automatic, no separate form; priority by 25 November 2026 for the Priority Round (rolling until 30 June 2027)", "For the Future Leaders Award (need-based, separate application by 2 December 2026): Statement of Circumstance, Declaration on Family Finances, reference/recommendation letter", "Identity documents supporting the claimed local/non-local status during the admissions process"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"round": "2027/28 entry - Priority Round", "opens": "2026-10-02", "deadline": "2026-11-25", "offers_from": "2026-12", "status": "open"}, {"round": "2027/28 entry - rolling", "from": "2026-11-26", "closes": "2027-06-30", "status": "open"}, {"pattern": "Annual: application opens early October, Priority Round deadline late November (offers from late December), rolling applications until the end of June; academic scholarship decisions ride on the admission offers"}]$json$ WHERE id = 51 RETURNING id, title, source_reliability;

