-- 5) university_scholarships sync (corrected run; max_scholarship is text NOT NULL)
UPDATE university_scholarships SET scholarship_name = 'HKU Entrance Scholarships (non-local undergraduate entry)', availability_status = 'international_students', funding_type = 'Merit-tiered entrance awards, automatic with the admission application: top-ranking non-locals up to full tuition waiver (composition fee HK$224,000-249,000/yr, 2026-27) plus accommodation scholarship and living allowance per year; lower tiers partial', max_scholarship = 'Up to full tuition waiver + accommodation scholarship + living allowance per year (top tier)', eligibility_notes = 'Automatic for all International/Non-JUPAS applicants; selection on academic merit with consideration of non-academic achievements; result announced with the admission offer; renewals expect satisfactory performance (cGPA 3.0+ in the conditions of award)', official_url = 'https://admissions.hku.hk/fees-and-scholarships/scholarships', source_url = 'https://admissions.hku.hk/fees-and-scholarships/scholarships', verification_status = 'verified', last_verified_at = now() WHERE id = 523 RETURNING id;
UPDATE university_scholarships SET scholarship_name = 'CUHK Admission Scholarships (incl. non-local students)', availability_status = 'international_students', funding_type = 'Automatic merit awards, no application: HK$5,000 to full-tuition coverage, many renewable for the normative period on satisfactory progress, some with allowance up to HK$66,000/yr; CUHK nominates first-years for the HKSAR Government Scholarship (HK$80,000/yr non-local) and Belt and Road Scholarship (tuition coverage)', max_scholarship = 'Up to full-tuition coverage; some awards add an allowance of up to HK$66,000 per year', eligibility_notes = 'Local and non-local new undergraduates (Mainland Gaokao, or other-regions qualifications meeting admission requirements); no application - the university identifies and informs selected students; government schemes by university nomination to the Education Bureau', official_url = 'https://admission.cuhk.edu.hk/fees-financing-your-studies/scholarships/admission-scholarships-for-undergraduates-only/', source_url = 'https://admission.cuhk.edu.hk/fees-financing-your-studies/scholarships/admission-scholarships-for-undergraduates-only/', verification_status = 'verified', last_verified_at = now() WHERE id = 473 RETURNING id;
UPDATE university_scholarships SET scholarship_name = 'HKUST Admissions Scholarships for Non-Local Applicants', availability_status = 'international_students', funding_type = 'Automatic academic awards: one-off or renewable full/partial tuition waivers up to full tuition (HK$260,000/yr, 2027/28) plus HK$65,000/yr allowance renewable; Global Learners full waiver for underrepresented nationalities; need-based Future Leaders and non-academic awards by separate application', max_scholarship = 'Up to full tuition + HK$65,000 per year allowance, renewable', eligibility_notes = 'All non-local applicants automatically considered (decision with the admission offer); renewals on satisfactory academic performance; Future Leaders Award needs documented exceptional financial need and a separate application by 2 December 2026', official_url = 'https://join.hkust.edu.hk/fees-and-scholarships', source_url = 'https://join.hkust.edu.hk/fees-and-scholarships', verification_status = 'verified', last_verified_at = now() WHERE id = 461 RETURNING id;

-- 6) Post-execution text-only correction applied live the same day (the main UPDATE for 51 above
--    is recorded here already in its corrected form; this statement is the one actually run live,
