UPDATE scholarships SET tuition_coverage = 'The tuition fee (HK$260,000/yr for non-locals in 2027/28) can be waived in part or in full; top packages add an allowance of up to HK$65,000 per year towards living costs (university accommodation ~HK$21,000-51,000/yr; personal expenses ~HK$65,000/yr).', last_updated_at = now() WHERE id = 51 RETURNING id, tuition_coverage;

